# ---------- イベントカレンダー ステータス更新 ----------
wse = wb["イベントカレンダー"]
today_d = datetime.date(2026,10,1)
def parse_d(v):
    if v is None: return None
    if isinstance(v, datetime.datetime): return v.date()
    if isinstance(v, datetime.date): return v
    s=str(v).strip()
    for fmt in ("%Y-%m-%d","%Y/%m/%d"):
        try: return datetime.datetime.strptime(s,fmt).date()
        except: pass
    return None
ev_updated=0
for r in range(2, wse.max_row+1):
    start=parse_d(wse.cell(r,1).value); end=parse_d(wse.cell(r,2).value)
    if start is None and end is None: continue
    cur=wse.cell(r,9).value; new=cur
    if end and end<today_d: new="終了"
    elif start and end and start<=today_d<=end: new="開催中"
    elif start and start<=today_d and not end: new="開催中"
    elif start and start>today_d: new="開催予定"
    if new and new!=cur:
        wse.cell(r,9).value=new; wse.cell(r,10).value=TODAY; style_row(wse,r); ev_updated+=1
print("EVENTS updated:", ev_updated)

